use maxt_bindings_common::schema::{Identifier, Schema, TaggedUnion, Type};

pub(crate) const HEADER: &str =
    "// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n";

pub(crate) fn lower_camel(value: &str) -> String {
    let mut characters = value.chars();
    match characters.next() {
        Some(first) => first.to_ascii_lowercase().to_string() + characters.as_str(),
        None => String::new(),
    }
}

pub(crate) fn render(schema: &Schema) -> String {
    let mut output = String::from(HEADER);
    output.push_str("\nexport type DecimalWire = string;\nexport type TimestampWire = string;\n");
    output.push_str("export type MarketKindWire = \"spot\" | \"perpetual\";\n\n");
    for record in &schema.records {
        output.push_str(&format!(
            "export interface {}{} {{\n",
            record.name,
            type_parameters(record.type_parameters)
        ));
        for field in &record.fields {
            output.push_str(&format!(
                "  readonly {}: {};\n",
                field.name,
                ts_type(&field.ty)
            ));
        }
        output.push_str("}\n\n");
    }
    for union in &schema.unions {
        render_union(&mut output, union);
    }
    output.push_str(&format!(
        "export const EXCHANGES = [{}] as const;\n",
        quoted(&schema.exchanges)
    ));
    output.push_str(&format!(
        "export const NATIVE_API_VERSION = {} as const;\n",
        schema.native_api_version
    ));
    output.push_str(&format!(
        "export const FEATURES = [{}] as const;\n",
        quoted(&schema.features)
    ));
    output.push_str(&format!(
        "export const ERROR_VARIANTS = [{}] as const;\n",
        quoted(schema.errors)
    ));
    output.push_str(&format!(
        "export const ADAPTER_OPERATIONS = [{}] as const;\n",
        quoted(
            schema
                .adapter_operations
                .iter()
                .map(|operation| operation.language_name)
        )
    ));
    output.push_str(&format!(
        "export const CLIENT_MEMBERS = [{}] as const;\n",
        quoted(schema.client_members)
    ));
    output.push_str("export const PROVIDER_METHODS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(provider.methods.iter().map(|method| method.name))
        ));
    }
    output.push_str("} as const;\nexport const PROVIDER_CONSTRUCTORS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(
                provider
                    .constructors
                    .iter()
                    .map(|constructor| constructor.name)
            )
        ));
    }
    output.push_str("} as const;\n");
    output.push_str(&format!(
        "export const IDENTIFIERS = [{}] as const;\n",
        quoted(schema.identifiers.iter().map(|value| value.name))
    ));
    output.push_str(&format!(
        "export const MODELS = [{}] as const;\n",
        quoted(schema.models)
    ));
    let raw_native_exports = ["NATIVE_API_VERSION", "NativeClient", "createCustomClient"]
        .into_iter()
        .map(str::to_owned)
        .chain(schema.providers.iter().flat_map(|provider| {
            [
                provider.native_handle.trim_end_matches("Handle").to_owned(),
                provider.native_factory.to_owned(),
            ]
        }))
        .collect::<Vec<_>>();
    output.push_str(&format!(
        "export const RAW_NATIVE_EXPORTS = [{}] as const;\n",
        quoted(raw_native_exports)
    ));
    output.push_str(&format!(
        "export const RAW_NATIVE_CLIENT_MEMBERS = [{}] as const;\n",
        quoted(
            ["exchange", "supports"]
                .into_iter()
                .chain(schema.adapter_operations.iter().flat_map(|operation| {
                    operation
                        .client_methods
                        .iter()
                        .map(|method| method.native_name)
                }))
                .chain(["streamNext", "streamClose"])
        )
    ));
    output.push_str("export const RAW_PROVIDER_MEMBERS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(
                std::iter::once("client").chain(provider.methods.iter().map(|method| method.name))
            )
        ));
    }
    output.push_str("} as const;\n");
    output
}

pub(crate) fn render_identifiers(schema: &Schema) -> String {
    let mut output = String::from(HEADER);
    output.push_str(
        r#"
class StringValue {
  protected constructor(readonly id: string) {}
  toString(): string { return this.id; }
}

"#,
    );
    for identifier in schema.identifiers {
        render_identifier(&mut output, identifier);
    }
    output.truncate(output.trim_end().len());
    output.push('\n');
    output
}

fn render_identifier(output: &mut String, identifier: &Identifier) {
    output.push_str(&format!(
        "export class {} extends StringValue {{\n",
        identifier.name
    ));
    for variant in identifier.variants {
        output.push_str(&format!(
            "  static readonly {} = new {}(\"{}\"{});\n",
            variant.rust_name,
            identifier.name,
            variant.wire_name,
            variant_argument(identifier.name, variant.rust_name, variant.wire_name),
        ));
    }
    output.push_str(&format!(
        "  static readonly values: readonly {}[] = Object.freeze([\n",
        identifier.name
    ));
    for variant in identifier.variants {
        output.push_str(&format!("    {}.{},\n", identifier.name, variant.rust_name));
    }
    output.push_str("  ]);\n");
    output.push_str(identifier_body(identifier.name, identifier.open));
    output.push_str("}\n\n");
}

fn variant_argument(identifier: &str, rust_name: &str, wire_name: &str) -> String {
    match identifier {
        "Exchange" => format!(", \"{rust_name}\""),
        "Interval" => format!(", {}", interval_seconds(wire_name)),
        _ => String::new(),
    }
}

fn interval_seconds(value: &str) -> String {
    let (prefix, multiplier) = if let Some(value) = value.strip_prefix("sec") {
        (value, 1)
    } else if let Some(value) = value.strip_prefix("min") {
        (value, 60)
    } else if let Some(value) = value.strip_prefix("hour") {
        (value, 3_600)
    } else if let Some(value) = value.strip_prefix("day") {
        (value, 86_400)
    } else if let Some(value) = value.strip_prefix("week") {
        (value, 604_800)
    } else if value.starts_with("month") {
        return "null".to_owned();
    } else {
        panic!("unsupported Interval wire name: {value}");
    };
    prefix
        .parse::<u64>()
        .map(|count| (count * multiplier).to_string())
        .unwrap_or_else(|_| panic!("unsupported Interval wire name: {value}"))
}

fn identifier_body(name: &str, open: bool) -> &'static str {
    match name {
        "Exchange" => {
            "  private constructor(id: string, readonly displayName: string) { super(id); Object.freeze(this); }\n"
        }
        "Feature" => {
            r#"  private constructor(id: string) {
    super(id);
    this.needsCredentials = new Set([
      "balances", "open_orders", "account_stream", "trading", "positions", "margin",
      "funding_payments", "margin_config", "reduce_only_orders",
    ]).has(id);
    this.isDerivativesOnly = new Set([
      "positions", "margin", "funding_rates", "funding_payments", "margin_config",
      "reduce_only_orders",
    ]).has(id);
    Object.freeze(this);
  }
  readonly needsCredentials: boolean;
  readonly isDerivativesOnly: boolean;
"#
        }
        "MarketKind" => {
            "  private constructor(id: string) { super(id); this.isDerivative = id !== \"spot\"; Object.freeze(this); }\n  readonly isDerivative: boolean;\n"
        }
        "Side" => {
            "  private constructor(id: string) { super(id); Object.freeze(this); }\n  get flipped(): Side { return this === Side.Buy ? Side.Sell : Side.Buy; }\n"
        }
        "Interval" => {
            "  private constructor(id: string, readonly seconds: number | null) { super(id); Object.freeze(this); }\n"
        }
        "OrderStatus" => {
            "  private constructor(id: string) { super(id); this.isLive = new Set([\"accepted\", \"open\", \"partially_filled\"]).has(id); Object.freeze(this); }\n  readonly isLive: boolean;\n"
        }
        "ExchangeErrorKind" => {
            "  private constructor(id: string) { super(id); this.retryable = id === \"rate_limited\" || id === \"unavailable\"; Object.freeze(this); }\n  private readonly retryable: boolean;\n  isRetryable(): boolean { return this.retryable; }\n"
        }
        "HyperliquidLedgerKind" if open => {
            "  private constructor(id: string) { super(id); Object.freeze(this); }\n  static other(value: string): HyperliquidLedgerKind { return new HyperliquidLedgerKind(value); }\n"
        }
        _ => "  private constructor(id: string) { super(id); Object.freeze(this); }\n",
    }
}

fn quoted(values: impl IntoIterator<Item = impl AsRef<str>>) -> String {
    values
        .into_iter()
        .map(|value| format!("\"{}\"", value.as_ref()))
        .collect::<Vec<_>>()
        .join(", ")
}

fn ts_type(value: &Type) -> String {
    match value {
        Type::String => "string".to_owned(),
        Type::Boolean => "boolean".to_owned(),
        Type::Number => "number".to_owned(),
        Type::Decimal => "DecimalWire".to_owned(),
        Type::Timestamp => "TimestampWire".to_owned(),
        Type::Identifier(_) => "string".to_owned(),
        Type::Named(name) => (*name).to_owned(),
        Type::Optional(value) => format!("{} | null", ts_type(value)),
        Type::List(value) => format!("readonly {}[]", ts_type(value)),
        Type::Tuple(values) => format!(
            "readonly [{}]",
            values.iter().map(ts_type).collect::<Vec<_>>().join(", ")
        ),
    }
}

fn render_union(output: &mut String, union: &TaggedUnion) {
    output.push_str(&format!(
        "export type {}{} =\n",
        union.name,
        type_parameters(union.type_parameters)
    ));
    for (index, variant) in union.variants.iter().enumerate() {
        output.push_str(if index == 0 { "  | {" } else { "\n  | {" });
        output.push_str(&format!(" readonly kind: \"{}\";", variant.name));
        for field in &variant.fields {
            output.push_str(&format!(
                " readonly {}: {};",
                field.name,
                ts_type(&field.ty)
            ));
        }
        output.push_str(" }");
    }
    output.push_str(";\n\n");
}

fn type_parameters(values: &[&str]) -> String {
    if values.is_empty() {
        String::new()
    } else {
        format!("<{}>", values.join(", "))
    }
}

#[cfg(test)]
mod tests {
    use maxt_bindings_common::schema::binding_schema;

    use super::render_identifiers;

    #[test]
    fn identifiers_are_rendered_from_the_schema_with_public_helpers() {
        let output = render_identifiers(&binding_schema());

        assert!(output.contains("export class Feature extends StringValue"));
        assert!(output.contains("static readonly Markets = new Feature(\"markets\")"));
        assert!(output.contains("static readonly values: readonly Feature[]"));
        assert!(output.contains("get flipped(): Side"));
        assert!(output.contains("readonly seconds: number | null"));
        assert!(output.contains("readonly isLive: boolean"));
        assert!(output.contains("isRetryable(): boolean"));
        assert!(output.contains("static other(value: string): HyperliquidLedgerKind"));
    }
}
